import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Banknote, Check, Download, Landmark, Plus, RefreshCw, ShieldCheck, Wallet, X } from 'lucide-react';
import { api, type Assignee, type TeamUser } from './api';
import './finance.css';
import { FINANCE_CATEGORIES, DRE_GROUPS, financeReport, type FinanceState, type FinanceCommand, type DreValues } from '../../shared/finance.mjs';

const money=(cents:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
const amount=(value:string)=>Math.round(Number(value.replace(',','.'))*100);
const percent=(value:number|null|undefined)=>value==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(value)+'%';
const today=()=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(type=>parts.find(part=>part.type===type)?.value).join('-');};
const currentMonth=()=>today().slice(0,7);
const dateLabel=(value:string)=>value?value.slice(0,10).split('-').reverse().join('/'):'—';
const monthLabel=(value:string)=>new Date(value+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'numeric'});
const csvCell=(value:unknown)=>{let text=String(value??'');if(/^[\s]*[=+@\-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
function downloadCsv(name:string,rows:unknown[][]){const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

type Option={value:string;label:string};
type Field={key:string;label:string;type?:'text'|'date'|'month'|'number'|'textarea'|'select';options?:Option[];value?:string;required?:boolean;help?:string;full?:boolean;min?:string;max?:string;step?:string};
type FormValues=Record<string,string>;
function FinanceModal({title,description,children,onClose}:{title:string;description?:string;children:ReactNode;onClose:()=>void}){
  const ref=useRef<HTMLDialogElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.showModal();return()=>{document.body.style.overflow=overflow;if(previous?.isConnected)previous.focus();};},[]);
  return <dialog ref={ref} className="pf-modal" aria-label={title} onCancel={e=>{e.preventDefault();onClose();}}><header><div><span className="ps-overline">EME SELECT · FINANCEIRO</span><h2>{title}</h2></div><button className="ps-icon" onClick={onClose} aria-label="Fechar formulário"><X size={20}/></button></header><div className="pf-modal-body">{description&&<p className="pf-modal-description">{description}</p>}{children}</div></dialog>;
}
function FinanceForm({fields,onSubmit,onClose,onReload,submitLabel='Salvar registro',children}:{fields:Field[];onSubmit:(values:FormValues)=>Promise<void>;onClose:()=>void;onReload?:()=>Promise<boolean>;submitLabel?:string;children?:ReactNode}){
  const [values,setValues]=useState<FormValues>(()=>Object.fromEntries(fields.map(field=>[field.key,field.value??'']))),[busy,setBusy]=useState(false),[error,setError]=useState('');
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError('');try{await onSubmit(values);}catch(error){setError((error as Error).message);}finally{setBusy(false);}}
  return <form className="pf-form" onSubmit={submit}><div className="pf-form-grid">{fields.map((field,index)=><label key={field.key} className={'pf-field'+(field.full?' pf-field--full':'')}>{field.label}{field.type==='select'?<select aria-label={field.label} value={values[field.key]} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}><option value="">{field.required===false?'Sem vínculo / não informado':'Selecione'}</option>{field.options?.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select>:field.type==='textarea'?<textarea aria-label={field.label} value={values[field.key]} rows={3} maxLength={1200} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}/>:<input aria-label={field.label} autoFocus={index===0} value={values[field.key]} type={field.type??'text'} min={field.min} max={field.max} step={field.step??(field.type==='number'?'0.01':undefined)} maxLength={240} required={field.required!==false} onChange={event=>setValues(previous=>({...previous,[field.key]:event.target.value}))}/>} {field.help&&<small>{field.help}</small>}</label>)}</div>{children}{error&&<div className="pt-error" role="alert"><p>{error}</p>{onReload&&<button type="button" className="ps-text-button" disabled={busy} onClick={async()=>{setBusy(true);if(await onReload())setError('Dados atualizados. Seus campos foram preservados; confira e tente salvar novamente.');setBusy(false);}}>Atualizar dados do financeiro</button>}</div>}<div className="pf-form-footer"><button type="button" disabled={busy} className="ps-button" onClick={onClose}>Cancelar</button><button className="ps-button ps-button--primary" disabled={busy}>{busy?'Salvando…':submitLabel}<Check size={16}/></button></div></form>;
}
function Metric({label,value,note,negative=false}:{label:string;value:string;note:string;negative?:boolean}){return <article className="pf-metric"><span>{label}</span><strong className={negative?'pf-negative':undefined}>{value}</strong><small>{note}</small></article>;}
function Empty({title,description,action,onAction}:{title:string;description:string;action?:string;onAction?:()=>void}){return <div className="pf-empty"><Wallet size={28}/><h3>{title}</h3><p>{description}</p>{action&&<button className="ps-button ps-button--primary" onClick={onAction}>{action}<Plus size={16}/></button>}</div>;}
function Notice({children,warning=false}:{children:ReactNode;warning?:boolean}){return <div className={'pf-callout'+(warning?' pf-callout--warning':'')}><ShieldCheck size={17}/><p>{children}</p></div>;}

type FinanceHistory={id:string|number;action:string;detail?:string;author?:string;created_at?:string;createdAt?:string};
type Snapshot={version:number;state:FinanceState;history:FinanceHistory[];members?:Assignee[];properties?:{id:string;title:string}[]};
type ModalState={kind:'account'|'entry'|'settle'|'cancel'|'recurrence'|'generate'|'operation'|'cancel-operation'|'partner'|'settings'|'adjustment'|'cancel-adjustment';id?:string;category?:string};
const tabs=[['overview','Visão geral'],['entries','Lançamentos'],['accounts','Contas'],['recurrences','Recorrências'],['operations','Operações e corretores'],['partners','Sócios e regras'],['reports','DRE e projeções']] as const;
const categoryLabel=(id:string)=>FINANCE_CATEGORIES.find(category=>category.id===id)?.label??id;
const actionLabel=(action:string)=>({'account.save':'Conta atualizada','entry.save':'Lançamento registrado','entry.settle':'Baixa registrada','entry.cancel':'Lançamento cancelado','recurrence.save':'Recorrência atualizada','recurrence.generate':'Competência gerada','operation.create':'Operação registrada','operation.cancel':'Operação cancelada','partner.save':'Sócio atualizado','settings.save':'Regras financeiras atualizadas','adjustment.save':'Ajuste de DRE registrado','adjustment.cancel':'Ajuste de DRE cancelado'}[action]??action);
const entryStatus=(status:string)=>status==='settled'?'Baixado':status==='cancelled'?'Cancelado':'Em aberto';
const moneyField=(key:string,label:string,value?:number|null,help?:string):Field=>({key,label:label+' (R$)',type:'number',min:'0',value:value==null?'':String(value/100),help});
const percentageField=(key:string,label:string,value?:number|null):Field=>({key,label:label+' (%)',type:'number',min:'0',max:'100',value:value==null?'':String(value/100)});
const dreRows:{key:keyof DreValues;label:string;total?:boolean}[]=[{key:'revenueCents',label:'Receita bruta da EME'},{key:'deductionsCents',label:'(−) Deduções da receita'},{key:'netRevenueCents',label:'Receita líquida',total:true},{key:'directCostCents',label:'(−) Comissões e custos diretos'},{key:'grossProfitCents',label:'Lucro bruto',total:true},{key:'operatingExpensesCents',label:'(−) Despesas operacionais e pró-labore'},{key:'operatingProfitCents',label:'Resultado operacional',total:true},{key:'financialIncomeCents',label:'(+) Receitas financeiras'},{key:'financialExpenseCents',label:'(−) Despesas financeiras'},{key:'incomeTaxCents',label:'(−) Tributos sobre o resultado'},{key:'netProfitCents',label:'Lucro líquido gerencial',total:true}];

export default function FinanceWorkspace({user,members:initialMembers,properties:initialProperties}:{user:TeamUser;members:Assignee[];properties:{id:string;title:string}[]}){
  const [snapshot,setSnapshot]=useState<Snapshot|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[conflict,setConflict]=useState(false);
  const retryCommand=useRef<{fingerprint:string;body:{version:number;requestId:string;command:FinanceCommand}}|null>(null);
  const [tab,setTab]=useState<(typeof tabs)[number][0]>('overview'),[month,setMonth]=useState(currentMonth),[modal,setModal]=useState<ModalState|null>(null);
  const [query,setQuery]=useState(''),[categoryFilter,setCategoryFilter]=useState(''),[centerFilter,setCenterFilter]=useState('');
  async function refresh(){setLoading(true);setError('');try{setSnapshot(await api<Snapshot>('/finance'));setConflict(false);return true;}catch(error){setError((error as Error).message);return false;}finally{setLoading(false);}}
  useEffect(()=>{if(user.role==='admin')void refresh();},[user.id,user.role]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(timer);},[toast]);
  async function command(type:string,data:Record<string,unknown>,message='Registro salvo no financeiro.'){
    if(!snapshot)return;
    if(conflict)throw new Error('Os dados foram alterados por outra pessoa. Atualize os dados abaixo, confira os valores e salve novamente.');
    const fingerprint=JSON.stringify({type,data});
    const pending=retryCommand.current?.fingerprint===fingerprint?retryCommand.current:{fingerprint,body:{version:snapshot.version,requestId:crypto.randomUUID(),command:{type,data} as FinanceCommand}};
    retryCommand.current=pending;
    try{const updated=await api<Snapshot>('/finance/commands','POST',pending.body);retryCommand.current=null;setSnapshot(updated);setModal(null);setToast(message);}
    catch(error){if((error as {status?:number}).status===409){retryCommand.current=null;setConflict(true);}throw error;}
  }
  const state=snapshot?.state;
  const from=month+'-01',to=month+'-'+String(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0,12).getDate()).padStart(2,'0');
  const members=snapshot?.members??initialMembers,properties=snapshot?.properties??initialProperties;
  const report=useMemo(()=>state?financeReport(state,{from,to,asOf:today()},members):null,[state,from,to,members]);
  const memberName=(id?:string|null)=>members.find(member=>member.id===id)?.name??(id?'Corretor cadastrado':'Não vinculado');
  const propertyName=(id?:string|null)=>properties.find(property=>property.id===id)?.title??(id?'Imóvel cadastrado':'Não vinculado');
  const accountName=(id?:string|null)=>state?.accounts.find(account=>account.id===id)?.name??'Sem conta vinculada';
  const centers=[...new Set(state?.entries.map(entry=>entry.costCenter).filter(Boolean)??[])];
  const entries=state?.entries.filter(entry=>entry.competenceDate.slice(0,7)===month&&(!categoryFilter||entry.category===categoryFilter)&&(!centerFilter||entry.costCenter===centerFilter)&&(!query||(entry.description+' '+categoryLabel(entry.category)).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))??[];
  const close=()=>setModal(null);
  const categoryOptions:Option[]=FINANCE_CATEGORIES.map(category=>({value:category.id,label:category.label}));
  const accountOptions:Option[]=state?.accounts.filter(account=>account.active).map(account=>({value:account.id,label:account.name}))??[];
  const peopleOptions:Option[]=members.map(member=>({value:member.id,label:member.name}));
  const propertyOptions:Option[]=properties.map(property=>({value:property.id,label:property.title}));
  const partnerOptions:Option[]=state?.partners.filter(partner=>partner.active).map(partner=>({value:partner.id,label:partner.name}))??[];
  const relationFields=(existing:{brokerId?:string|null;propertyId?:string|null;partnerId?:string|null;costCenter?:string}={}):Field[]=>[
    {key:'brokerId',label:'Corretor vinculado',type:'select',options:peopleOptions,required:false,value:String(existing.brokerId??'')},
    {key:'propertyId',label:'Imóvel vinculado',type:'select',options:propertyOptions,required:false,value:String(existing.propertyId??'')},
    {key:'partnerId',label:'Sócio vinculado',type:'select',options:partnerOptions,required:false,value:String(existing.partnerId??'')},
    {key:'costCenter',label:'Centro de custo',required:false,value:String(existing.costCenter??''),help:'Ex.: Institucional, Captação, Balneário Camboriú.'},
  ];
  function exportEntries(){downloadCsv('eme-financeiro-'+month+'.csv',[
    ['Descrição','Categoria','Centro de custo','Valor (R$)','Competência','Vencimento','Baixa','Situação','Reconhecimento','Conta','Corretor','Imóvel'],
    ...entries.map(entry=>[entry.description,categoryLabel(entry.category),entry.costCenter,(entry.amountCents/100).toFixed(2).replace('.',','),entry.competenceDate,entry.dueDate,entry.settledDate,entryStatus(entry.status),entry.recognition==='recognized'?'Realizado':'Previsão',accountName(entry.accountId),memberName(entry.brokerId),propertyName(entry.propertyId)]),
  ]);}
  function renderForm(){
    if(!modal||!state)return null;
    if(modal.kind==='account'){
      const existing=state.accounts.find(account=>account.id===modal.id);
      const fields:Field[]=[{key:'name',label:'Nome da conta',value:existing?.name,help:'Um nome fácil de reconhecer, como Conta principal ou Caixa físico.'},{key:'kind',label:'Tipo de conta',type:'select',value:existing?.kind??'bank',options:[{value:'bank',label:'Conta bancária'},{value:'cash',label:'Caixa físico'}]},{key:'bankName',label:'Banco / instituição',required:false,value:existing?.bankName},{key:'openingDate',label:'Data do saldo inicial',type:'date',value:existing?.openingDate??today()},{...moneyField('openingBalanceCents','Saldo total inicial',existing?.openingBalanceCents??0,'Pode ser negativo. Use o saldo conferido no extrato dessa data.'),min:undefined},moneyField('openingThirdPartyCents','Parcela pertencente a terceiros',existing?.openingThirdPartyCents??0,'Aluguéis e valores a repassar. Essa parcela não é receita da EME.')];
      return <FinanceModal title={existing?'Editar conta manual':'Adicionar conta manual'} description="Registre o saldo de partida. Entradas e saídas baixadas nesta conta formarão o saldo interno; nenhuma conexão ou movimentação bancária é realizada." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={values=>command('account.save',{...values,id:existing?.id,openingBalanceCents:amount(values.openingBalanceCents),openingThirdPartyCents:amount(values.openingThirdPartyCents),active:existing?.active??true})}/></FinanceModal>;
    }
    if(modal.kind==='entry'){
      const existing=state.entries.find(entry=>entry.id===modal.id);
      const fields:Field[]=[{key:'description',label:'Descrição do lançamento',full:true,value:existing?.description},{key:'category',label:'Categoria',type:'select',options:categoryOptions,value:existing?.category??modal.category},moneyField('amountCents','Valor',existing?.amountCents),{key:'recognition',label:'Reconhecimento',type:'select',value:existing?.recognition??'recognized',options:[{value:'recognized',label:'Realizado · compõe a DRE'},{value:'forecast',label:'Previsão · apenas planejamento'}],help:'Realizado significa ganho ou incorrido, mesmo que ainda não tenha sido pago.'},{key:'behavior',label:'Comportamento do custo',type:'select',value:existing?.behavior??'variable',options:[{value:'variable',label:'Variável / por operação'},{value:'fixed',label:'Fixo / recorrente'}]},{key:'competenceDate',label:'Data de competência',type:'date',value:existing?.competenceDate??today()},{key:'dueDate',label:'Data de vencimento',type:'date',value:existing?.dueDate??today()},...relationFields(existing),{key:'notes',label:'Observações',type:'textarea',full:true,required:false,value:existing?.notes,help:'Anote comprovante, fornecedor, contrato ou contexto. Não inclua senhas bancárias.'}];
      return <FinanceModal title={existing?'Editar lançamento':'Novo lançamento'} description="Receitas, despesas, aportes, pró-labore e repasses têm tratamentos diferentes. Escolha a categoria pela natureza do valor. A baixa é registrada em uma etapa separada. Use “Taxa de administração retida do aluguel” quando a remuneração é descontada de valores de terceiros já recebidos." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={values=>command('entry.save',{...values,id:existing?.id,amountCents:amount(values.amountCents)})}/></FinanceModal>;
    }
    if(modal.kind==='settle'){
      const existing=state.entries.find(entry=>entry.id===modal.id);if(!existing)return null;
      const transfer=FINANCE_CATEGORIES.find(category=>category.id===existing.category)?.direction==='transfer';
      return <FinanceModal title="Registrar baixa" description={existing.description+' · '+money(existing.amountCents)+(existing.category==='management_fee_retained'?'. A taxa será descontada dos valores de terceiros já registrados, sem criar um novo depósito.':'. Confirme uma movimentação que já ocorreu. Esse registro não faz pagamentos nem transferências.')} onClose={close}><FinanceForm fields={[{key:'accountId',label:transfer?'Conta de origem':'Conta da movimentação',type:'select',options:accountOptions,value:existing.accountId??''},{key:'settledDate',label:'Data do recebimento / pagamento',type:'date',value:today()},...(transfer?[{key:'destinationAccountId',label:'Conta de destino',type:'select' as const,options:accountOptions}]:[])]} onClose={close} onReload={refresh} submitLabel="Confirmar baixa" onSubmit={values=>command('entry.settle',{id:existing.id,...values},'Baixa registrada. Os saldos internos foram atualizados.')}><Notice>Registre cada movimentação uma única vez. A baixa transforma uma previsão em realizado, preservando a competência informada.</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='cancel'||modal.kind==='cancel-adjustment'||modal.kind==='cancel-operation'){
      return <FinanceModal title="Cancelar registro" description={modal.kind==='cancel-operation'?'A operação e todos os seus lançamentos serão cancelados em conjunto, preservando o histórico. Se houve movimentação bancária real, confira também o estorno no banco.':'O registro continuará no histórico com a justificativa. Se houve movimentação bancária real, confira também o estorno no banco.'} onClose={close}><FinanceForm fields={[{key:'reason',label:'Motivo do cancelamento',type:'textarea',full:true}]} onClose={close} onReload={refresh} submitLabel="Confirmar cancelamento" onSubmit={values=>command(modal.kind==='cancel'?'entry.cancel':modal.kind==='cancel-operation'?'operation.cancel':'adjustment.cancel',{id:modal.id,reason:values.reason},'Cancelamento registrado no histórico.')}/></FinanceModal>;
    }
    if(modal.kind==='recurrence'){
      const existing=state.recurrences.find(recurrence=>recurrence.id===modal.id);
      const fields:Field[]=[{key:'name',label:'Descrição da recorrência',full:true,value:existing?.name},{key:'category',label:'Categoria',type:'select',options:categoryOptions.filter(option=>!['transfer','partner_distribution','capital_in','loan_in','investment'].includes(option.value)),value:existing?.category},moneyField('amountCents','Valor mensal',existing?.amountCents),{key:'behavior',label:'Comportamento',type:'select',value:existing?.behavior??'fixed',options:[{value:'fixed',label:'Fixo'},{value:'variable',label:'Variável'}]},{key:'dueDay',label:'Dia do vencimento',type:'number',min:'1',max:'28',step:'1',value:String(existing?.dueDay??10),help:'De 1 a 28 para manter a mesma data em todos os meses.'},{key:'startMonth',label:'Mês de início',type:'month',value:existing?.startMonth??month},{key:'endMonth',label:'Mês de término',type:'month',required:false,value:existing?.endMonth??''},...relationFields(existing)];
      return <FinanceModal title={existing?'Editar recorrência':'Nova recorrência mensal'} description="Cadastre honorários mensais da EME ou despesas recorrentes. Depois, gere a competência desejada; gerar novamente o mesmo mês não cria duplicidade." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} onSubmit={values=>command('recurrence.save',{...values,id:existing?.id,amountCents:amount(values.amountCents),dueDay:Number(values.dueDay),active:existing?.active??true})}/></FinanceModal>;
    }
    if(modal.kind==='generate'){
      const existing=state.recurrences.find(recurrence=>recurrence.id===modal.id);if(!existing)return null;
      return <FinanceModal title="Gerar competência" description={existing.name+' · '+money(existing.amountCents)+' por mês. O lançamento ficará em aberto para conferência e baixa.'} onClose={close}><FinanceForm fields={[{key:'month',label:'Mês de competência',type:'month',value:month}]} onClose={close} onReload={refresh} submitLabel="Gerar lançamento" onSubmit={values=>command('recurrence.generate',{id:existing.id,month:values.month},'Competência gerada ou já existente; sem duplicar o lançamento.')}/></FinanceModal>;
    }
    if(modal.kind==='operation'){
      const fields:Field[]=[{key:'title',label:'Nome da operação',full:true},{key:'kind',label:'Tipo de operação',type:'select',value:'sale',options:[{value:'sale',label:'Venda'},{value:'rental',label:'Intermediação de locação'},{value:'management',label:'Administração · taxa cobrada separadamente'},{value:'other',label:'Outro serviço'}]},moneyField('amountCents','Receita da EME',undefined,'Somente a comissão / honorário da empresa. Não use o preço do imóvel nem o aluguel do proprietário.'),percentageField('commissionBps','Participação do corretor na receita EME',state.settings.defaultCommissionBps),moneyField('directCostCents','Outros custos diretos',0,'Custos desta operação ainda não lançados, sem incluir a comissão acima.'),percentageField('reserveBps','Reserva da empresa nesta operação',state.settings.reserveBps),{key:'brokerId',label:'Corretor responsável',type:'select',options:peopleOptions,required:false},{key:'propertyId',label:'Imóvel vinculado',type:'select',options:propertyOptions,required:false},{key:'competenceDate',label:'Data de competência',type:'date',value:today()},{key:'dueDate',label:'Vencimento previsto',type:'date',value:today()},{key:'notes',label:'Observações da operação',type:'textarea',full:true,required:false}];
      return <FinanceModal title="Registrar operação" description="O portal cria uma receita e as despesas de comissão / custo direto correspondentes. Não lance esses valores novamente. Para taxa de administração retida do aluguel, use a categoria específica em Lançamentos ou Recorrências. A reserva é uma destinação gerencial, sem transferência bancária." onClose={close}><FinanceForm fields={fields} onClose={close} onReload={refresh} submitLabel="Criar operação" onSubmit={values=>command('operation.create',{...values,amountCents:amount(values.amountCents),commissionBps:amount(values.commissionBps),directCostCents:amount(values.directCostCents),reserveBps:amount(values.reserveBps)},'Operação criada com os lançamentos vinculados.')}><Notice>Use a regra acordada com o corretor e os sócios. Percentuais não preenchidos nas configurações precisam ser definidos nesta operação.</Notice></FinanceForm></FinanceModal>;
    }
    if(modal.kind==='partner'){
      const existing=state.partners.find(partner=>partner.id===modal.id);
      return <FinanceModal title={existing?'Editar sócio':'Adicionar sócio'} description="Informe a participação acordada para simular a distribuição de resultado. A simulação não realiza pagamentos." onClose={close}><FinanceForm fields={[{key:'name',label:'Nome do sócio',value:existing?.name},percentageField('shareBps','Participação na distribuição',existing?.shareBps)]} onClose={close} onReload={refresh} onSubmit={values=>command('partner.save',{id:existing?.id,name:values.name,shareBps:amount(values.shareBps),active:existing?.active??true})}/></FinanceModal>;
    }
    if(modal.kind==='settings'){
      return <FinanceModal title="Regras e metas da empresa" description="Os valores são definidos pela EME. Deixe em branco o que ainda não foi combinado. Alterar os padrões não recalcula operações antigas." onClose={close}><FinanceForm fields={[{...percentageField('reserveBps','Reserva padrão por operação',state.settings.reserveBps),required:false},{...percentageField('defaultCommissionBps','Comissão padrão do corretor',state.settings.defaultCommissionBps),required:false},{...moneyField('cashTargetCents','Meta de caixa próprio',state.settings.cashTargetCents),required:false},{...moneyField('initialInvestmentCents','Investimento inicial para payback',state.settings.initialInvestmentCents),required:false}]} onClose={close} onReload={refresh} onSubmit={values=>command('settings.save',Object.fromEntries(Object.entries(values).map(([key,value])=>[key,value===''?null:amount(value)])))}/></FinanceModal>;
    }
    if(modal.kind==='adjustment'){
      return <FinanceModal title="Ajuste gerencial da DRE" description="Use para ajustes de competência documentados. Não substitui um lançamento financeiro e não altera o caixa. Valores positivos aumentam o grupo escolhido; negativos reduzem." onClose={close}><FinanceForm fields={[{key:'label',label:'Descrição do ajuste',full:true},{key:'group',label:'Grupo da DRE',type:'select',options:DRE_GROUPS.map(group=>({value:group.id,label:group.label}))},{...moneyField('amountCents','Valor do ajuste'),min:undefined},{key:'competenceDate',label:'Data de competência',type:'date',value:today()},{key:'reason',label:'Justificativa e referência',type:'textarea',full:true}]} onClose={close} onReload={refresh} onSubmit={values=>command('adjustment.save',{...values,amountCents:amount(values.amountCents)},'Ajuste gerencial salvo separadamente dos lançamentos.')}/></FinanceModal>;
    }
    return null;
  }
  if(user.role!=='admin')return <Notice>O financeiro da empresa é restrito aos administradores.</Notice>;
  if(loading&&!snapshot)return <div className="pf-loading" role="status">Carregando o financeiro da EME…<div className="pf-skeleton"/></div>;
  if(!state||!report)return <div className="pf-workspace"><p className="pt-error" role="alert">{error||'Não foi possível carregar os dados.'}</p><button className="ps-button" onClick={refresh}>Tentar novamente<RefreshCw size={16}/></button></div>;
  return <section className="pf-workspace" aria-label="Central financeira"><div className="pf-toolbar"><div><span className="ps-overline">CONTROLE, RESULTADO E PRÓXIMOS PASSOS</span><p>As finanças da EME em um só lugar. Valores de proprietários permanecem separados da receita e do caixa próprio.</p></div><label className="pf-period">Competência selecionada<input type="month" min="1900-01" max="2200-12" value={month} onChange={event=>{const value=event.target.value;if(/^\d{4}-(0[1-9]|1[0-2])$/.test(value)&&value>='1900-01'&&value<='2200-12')setMonth(value);}}/></label></div><nav className="pf-tabs" aria-label="Seções do financeiro">{tabs.map(([id,label])=><button key={id} aria-current={tab===id?'page':undefined} onClick={()=>setTab(id)}>{label}</button>)}</nav>{error&&<p className="pt-error" role="alert">{error}</p>}
  {tab==='overview'&&<>
    <div className="pf-hero"><div><span className="ps-overline">CAIXA PRÓPRIO · SALDO ATUAL</span><h2>{money(report.cash.availableCents)}</h2><p>Disponível da empresa, descontados os valores de terceiros. Baseado nos saldos iniciais e nas baixas registradas até hoje.</p></div><div className="pf-hero-side"><div className="pf-hero-row"><span>Saldo total das contas</span><strong>{money(report.cash.balanceCents)}</strong></div><div className="pf-hero-row"><span>Valores de terceiros a repassar</span><strong>{money(report.cash.thirdPartyHeldCents)}</strong></div><div className="pf-hero-row"><span>Reserva sugerida acumulada</span><strong>{money(report.cash.reserveSuggestedCents)}</strong></div><div className="pf-hero-row"><span>Meta de caixa próprio</span><strong>{report.cash.targetCents==null?'Ainda não definida':money(report.cash.targetCents)}</strong></div></div></div>
    <div className="pf-grid"><Metric label={'Receita EME · '+monthLabel(month)} value={money(report.dre.combined.revenueCents)} note="Regime de competência · realizada"/><Metric label="Lucro bruto" value={money(report.dre.combined.grossProfitCents)} note="Após deduções, comissões e custos diretos" negative={report.dre.combined.grossProfitCents<0}/><Metric label="Lucro líquido gerencial" value={money(report.dre.combined.netProfitCents)} note="Inclui despesas, financeiro e tributos lançados" negative={report.dre.combined.netProfitCents<0}/><Metric label="MRR · recorrência ativa hoje" value={money(report.mrrCents)} note={'ARR anualizado: '+money(report.arrCents)}/></div>
    {!state.accounts.length&&<Empty title="Comece pelo saldo real da empresa." description="Cadastre suas contas com o saldo conferido no extrato. Depois, organize despesas, receitas e compromissos para acompanhar a evolução do caixa." action="Adicionar primeira conta" onAction={()=>setModal({kind:'account'})}/>}
    {report.warnings.length>0&&<details className="pf-warning-list"><summary>{report.warnings.length} pontos para conferir no financeiro</summary><ul>{report.warnings.map((warning,index)=><li key={index}>{warning}</li>)}</ul></details>}
    <div className="pf-split"><section className="pf-panel"><div className="pf-heading"><div><h3>O mês em movimento</h3><p>Recebimentos e pagamentos registrados em {monthLabel(month)}.</p></div><button className="ps-text-button" onClick={()=>setTab('entries')}>Ver lançamentos<ArrowRight size={14}/></button></div><div className="pf-list"><div className="pf-list-row"><span className="pf-inline"><ArrowDownLeft size={16}/>Recebimentos</span><strong>{money(report.period.receivedCents)}</strong></div><div className="pf-list-row"><span className="pf-inline"><ArrowUpRight size={16}/>Pagamentos</span><strong>{money(report.period.paidCents)}</strong></div><div className="pf-list-row"><span>Custos fixos da competência</span><strong>{money(report.period.fixedCostsCents)}</strong></div><div className="pf-list-row"><span>Custos variáveis da competência</span><strong>{money(report.period.variableCostsCents)}</strong></div><div className="pf-list-row"><span>A receber em atraso<small>Compromissos em aberto até hoje</small></span><strong>{money(report.period.overdueReceivableCents)}</strong></div><div className="pf-list-row"><span>A pagar em atraso</span><strong className={report.period.overduePayableCents?'pf-negative':undefined}>{money(report.period.overduePayableCents)}</strong></div></div><div className="pf-actions" style={{marginTop:20}}><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'entry'})}><Plus size={15}/>Lançar movimento</button><button className="ps-button" onClick={()=>setModal({kind:'operation'})}>Registrar operação</button></div></section><section className="pf-panel"><div className="pf-heading"><div><h3>Fôlego para crescer</h3><p>Metas e recuperação do investimento.</p></div><button className="ps-text-button" onClick={()=>setModal({kind:'settings'})}>Definir metas<ArrowRight size={14}/></button></div><div className="pf-list"><div className="pf-list-row"><span>Meta de caixa</span><strong>{report.cash.targetCents==null?'A definir':money(report.cash.targetCents)}</strong></div>{report.cash.targetCents!=null&&report.cash.targetCents>0&&<div><div className="pf-health-bar" role="meter" aria-label="Progresso da meta de caixa" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.max(0,Math.min(100,Math.round(report.cash.availableCents/report.cash.targetCents*100)))}><span style={{width:Math.max(0,Math.min(100,report.cash.availableCents/report.cash.targetCents*100))+'%'}}/></div><small className="pf-muted">{report.cash.gapCents&&report.cash.gapCents>0?money(report.cash.gapCents)+' para atingir a meta':'Meta atingida no saldo atual'}</small></div>}<div className="pf-list-row"><span>Investimento inicial</span><strong>{report.payback.investmentCents==null?'A definir':money(report.payback.investmentCents)}</strong></div><div className="pf-list-row"><span>Caixa operacional acumulado<small>Base gerencial da recuperação</small></span><strong className={report.payback.recoveredCents<0?'pf-negative':undefined}>{money(report.payback.recoveredCents)}</strong></div><div className="pf-list-row"><span>Prazo estimado restante</span><strong>{report.payback.reached?'Investimento recuperado':report.payback.monthsEstimate==null?'Sem base positiva':report.payback.monthsEstimate.toLocaleString('pt-BR',{maximumFractionDigits:1})+' meses'}</strong></div></div><p className="pf-note-line">Prazo para recuperar o investimento restante, pela média do caixa operacional dos meses completos. O mês em andamento fica fora da média. A estimativa não é garantia de retorno.</p></section></div>
    <section className="pf-panel"><div className="pf-heading"><div><h3>Onde estamos investindo</h3><p>Despesas por categoria na competência selecionada.</p></div><button className="ps-text-button" onClick={()=>setTab('reports')}>DRE e projeções<ArrowRight size={14}/></button></div>{report.period.byCategory.filter(item=>item.direction==='out'&&FINANCE_CATEGORIES.find(category=>category.id===item.category)?.dreGroup!=null).length?<div className="pf-list">{report.period.byCategory.filter(item=>item.direction==='out'&&FINANCE_CATEGORIES.find(category=>category.id===item.category)?.dreGroup!=null).sort((a,b)=>b.amountCents-a.amountCents).map(item=><div className="pf-list-row" key={item.category}><span>{item.label}</span><strong>{money(item.amountCents)}</strong></div>)}</div>:<p className="pf-muted">As despesas aparecerão aqui conforme forem registradas.</p>}</section>
  </>}
  {tab==='accounts'&&<><div className="pf-heading"><div><h2>Contas e caixa da empresa</h2><p>Controle manual com histórico de cada recebimento e pagamento.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'account'})}><Plus size={16}/>Adicionar conta</button></div><Notice>Os saldos são internos ao portal. Confira-os com seus extratos. A conexão Open Finance será uma etapa posterior; esta tela não acessa nem movimenta contas reais.</Notice>{!state.accounts.length?<Empty title="Suas contas, organizadas" description="Cadastre uma conta bancária ou o caixa físico da EME e informe o saldo inicial conferido." action="Cadastrar primeira conta" onAction={()=>setModal({kind:'account'})}/>:<div className="pf-account-grid">{state.accounts.map(account=><article className="pf-account" key={account.id}>{account.kind==='cash'?<Banknote size={24}/>:<Landmark size={24}/>}<h3>{account.name}</h3><p>{account.kind==='cash'?'Caixa físico':account.bankName||'Conta bancária manual'}{!account.active?' · Inativa':''}</p><strong className={(report.cash.accounts.find(item=>item.id===account.id)?.balanceCents??0)<0?'pf-negative':undefined}>{money(report.cash.accounts.find(item=>item.id===account.id)?.balanceCents??0)}</strong><small>Saldo inicial {money(account.openingBalanceCents)} em {dateLabel(account.openingDate)}</small><small>Terceiros no saldo inicial: {money(account.openingThirdPartyCents)}</small><button className="ps-text-button" style={{marginTop:18}} onClick={()=>setModal({kind:'account',id:account.id})}>Conferir dados<ArrowUpRight size={14}/></button></article>)}</div>}</>}
  {tab==='operations'&&<><section className="pf-panel"><div className="pf-heading"><div><h2>Cada operação, seu resultado.</h2><p>Receita da EME, participação do corretor, custo direto e reserva.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'operation'})}><Plus size={16}/>Nova operação</button></div>{!state.operations.filter(operation=>operation.competenceDate.slice(0,7)===month).length?<Empty title="Nenhuma operação nesta competência" description="Registre a comissão ou honorário da EME para criar os lançamentos vinculados e acompanhar a contribuição por corretor." action="Registrar operação" onAction={()=>setModal({kind:'operation'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Operação</th><th>Corretor</th><th className="pf-number">Receita EME</th><th className="pf-number">Comissão</th><th className="pf-number">Custo direto</th><th className="pf-number">Reserva</th><th>Ações</th></tr></thead><tbody>{state.operations.filter(operation=>operation.competenceDate.slice(0,7)===month).map(operation=><tr key={operation.id}><td><strong>{operation.title}</strong>{operation.status==='cancelled'&&<small>Cancelada</small>}<small>{propertyName(operation.propertyId)}</small><small>{dateLabel(operation.competenceDate)}</small></td><td>{memberName(operation.brokerId)}</td><td className="pf-number">{money(operation.amountCents)}</td><td className="pf-number">{money(operation.commissionCents)}<small>{percent(operation.commissionBps/100)}</small></td><td className="pf-number">{money(operation.directCostCents)}</td><td className="pf-number">{money(operation.reserveCents)}<small>{percent(operation.reserveBps/100)}</small></td><td>{operation.status!=='cancelled'&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel-operation',id:operation.id})}>Cancelar operação</button>}</td></tr>)}</tbody></table></div>}<p className="pf-note-line">Receita EME é a remuneração da empresa. A reserva sugerida acumulada é calculada sobre receitas de operações já recebidas. É uma referência de retenção, não um saldo bancário segregado nem uma despesa da DRE.</p></section><section className="pf-panel" style={{marginTop:20}}><div className="pf-heading"><div><h3>Resultado por corretor</h3><p>Contribuição antes das despesas gerais da empresa.</p></div></div>{!report.brokers.length?<p className="pf-muted">Vincule um corretor à operação ou ao lançamento para acompanhar seu resultado.</p>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Corretor</th><th>Operações</th><th className="pf-number">Receita</th><th className="pf-number">Comissão</th><th className="pf-number">Custos diretos</th><th className="pf-number">Contribuição</th><th className="pf-number">Recebido</th></tr></thead><tbody>{report.brokers.map(broker=><tr key={broker.id}><td><span className="pf-broker-name"><i>{broker.name.slice(0,1)}</i>{broker.name}</span></td><td>{broker.operations}</td><td className="pf-number">{money(broker.revenueCents)}</td><td className="pf-number">{money(broker.commissionCents)}</td><td className="pf-number">{money(broker.directCostCents)}</td><td className="pf-number"><strong className={broker.contributionCents<0?'pf-negative':undefined}>{money(broker.contributionCents)}</strong></td><td className="pf-number">{money(broker.receivedCents)}</td></tr>)}</tbody></table></div>}</section></>}
  {tab==='partners'&&<><section className="pf-panel"><div className="pf-heading"><div><h2>Regras claras para crescer juntos.</h2><p>Defina as participações e os padrões da empresa.</p></div><button className="ps-button" onClick={()=>setModal({kind:'settings'})}>Configurar regras<ArrowUpRight size={15}/></button></div><dl className="pf-setting-summary"><div><dt>Reserva padrão por operação</dt><dd>{state.settings.reserveBps==null?'A definir':percent(state.settings.reserveBps/100)}</dd></div><div><dt>Comissão padrão do corretor</dt><dd>{state.settings.defaultCommissionBps==null?'A definir':percent(state.settings.defaultCommissionBps/100)}</dd></div><div><dt>Meta de caixa</dt><dd>{state.settings.cashTargetCents==null?'A definir':money(state.settings.cashTargetCents)}</dd></div></dl><Notice>Pró-labore é uma despesa operacional e pode ser cadastrado como recorrência. Distribuição de lucros é uma destinação do resultado e não reduz o lucro da DRE.</Notice></section><div className="pf-split"><section className="pf-panel"><div className="pf-heading"><h3>Quadro de sócios</h3><button className="ps-button" onClick={()=>setModal({kind:'partner'})}><Plus size={15}/>Adicionar sócio</button></div>{!state.partners.length?<p className="pf-muted">Cadastre os sócios e os percentuais acordados. Nenhuma divisão é presumida.</p>:<div className="pf-list">{state.partners.map(partner=><div className="pf-list-row" key={partner.id}><span><strong>{partner.name}</strong><small>{partner.active?'Participação ativa':'Inativo'}</small></span><span>{percent(partner.shareBps/100)}</span><button className="ps-text-button" onClick={()=>setModal({kind:'partner',id:partner.id})}>Editar</button></div>)}</div>}<p className="pf-note-line">Participações ativas: {percent(report.distribution.allocatedBps/100)}. Para simular uma divisão completa, o total precisa ser 100%.</p></section><section className="pf-panel"><div className="pf-heading"><div><h3>Simulação de distribuição</h3><p>Referência gerencial para {monthLabel(month)}.</p></div></div><div className="pf-dre-row pf-dre-row--total"><span>Base disponível na simulação</span><strong>{money(report.distribution.eligibleCents)}</strong></div>{(!report.distribution.ready||report.distribution.eligibleCents<=0)?<Notice warning>Não há distribuição disponível nesta simulação. Confira o lucro positivo, o caixa livre após reservas e compromissos, e as participações dos sócios somando 100%.</Notice>:<div className="pf-list">{report.distribution.shares.map(share=><div className="pf-list-row" key={share.id}><span>{share.name}<small>{percent(share.shareBps/100)} da base</small></span><strong>{money(share.amountCents)}</strong></div>)}</div>}<p className="pf-note-line">Simulação, sem pagamento automático. Protege a maior referência entre meta de caixa e reserva sugerida acumulada, além de compromissos próprios de {money(report.distribution.commitmentsCents)} até {dateLabel(report.distribution.payableHorizon)}. A distribuição deve ser deliberada pelos sócios e conferida com a contabilidade. Registre uma retirada efetiva em Lançamentos, na categoria Distribuição de lucros.</p><button className="ps-text-button" style={{marginTop:14}} onClick={()=>setModal({kind:'entry',category:'partner_distribution'})}>Registrar retirada efetiva<ArrowRight size={14}/></button></section></div></>}
  {tab==='reports'&&<><section className="pf-panel"><div className="pf-heading"><div><h2>DRE gerencial</h2><p>Competência de {monthLabel(month)} · valores realizados e ajustes separados.</p></div><div className="pf-actions"><button className="ps-button" onClick={()=>downloadCsv('eme-dre-'+month+'.csv',[['Linha','Automático (R$)','Ajustes (R$)','Combinado (R$)'],...dreRows.map(row=>[row.label,...(['automatic','manual','combined'] as const).map(mode=>(report.dre[mode][row.key]/100).toFixed(2).replace('.',','))])])}><Download size={15}/>Exportar DRE</button><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'adjustment'})}><Plus size={15}/>Ajuste manual</button></div></div><div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Demonstração</th><th className="pf-number">Automático</th><th className="pf-number">Ajustes manuais</th><th className="pf-number">Combinado</th></tr></thead><tbody>{dreRows.map(row=><tr key={row.key} className={row.total?'pf-dre-row--total':undefined}><td>{row.label}</td><td className="pf-number">{money(report.dre.automatic[row.key])}</td><td className="pf-number">{money(report.dre.manual[row.key])}</td><td className="pf-number"><strong className={report.dre.combined[row.key]<0?'pf-negative':undefined}>{money(report.dre.combined[row.key])}</strong></td></tr>)}</tbody></table></div><div className="pf-grid" style={{marginBottom:0}}><Metric label="Margem bruta" value={percent(report.dre.combined.netRevenueCents>0?report.dre.combined.grossProfitCents/report.dre.combined.netRevenueCents*100:null)} note="Lucro bruto / receita líquida"/><Metric label="Margem líquida" value={percent(report.dre.combined.netRevenueCents>0?report.dre.combined.netProfitCents/report.dre.combined.netRevenueCents*100:null)} note="Lucro líquido / receita líquida"/><Metric label="MRR" value={money(report.mrrCents)} note="Receita mensal recorrente ativa hoje"/><Metric label="ARR" value={money(report.arrCents)} note="MRR × 12 · anualização, não caixa recebido"/></div><p className="pf-note-line">DRE gerencial baseada nos registros do portal. Revise classificação e tributos com a contabilidade. Aportes, transferências, empréstimos, repasses e distribuição de lucros ficam fora da receita e das despesas operacionais.</p></section>
    <section className="pf-panel" style={{marginTop:20}}><div className="pf-heading"><div><h3>Próximos seis meses</h3><p>Projeção pelos vencimentos em aberto e recorrências, sem duplicar competências já geradas.</p></div></div><div className="pf-projection" aria-label="Caixa próprio projetado">{report.projections.map(item=><div className="pf-projection-month" key={item.month}><span className={item.availableCents<0?'pf-negative':undefined}>{money(item.availableCents)}</span><i className={item.availableCents<0?'pf-bar-negative':undefined} style={{height:Math.max(3,Math.abs(item.availableCents)/Math.max(1,...report.projections.map(value=>Math.abs(value.availableCents)))*100)+'px'}}/><small>{monthLabel(item.month)}</small></div>)}</div><div className="pf-table-wrap" style={{marginTop:20}}><table className="pf-table"><thead><tr><th>Mês</th><th className="pf-number">Saldo inicial</th><th className="pf-number">Entradas totais</th><th className="pf-number">Saídas totais</th><th className="pf-number">Terceiros incluídos · entrada</th><th className="pf-number">Terceiros incluídos · saída</th><th className="pf-number">Caixa próprio</th></tr></thead><tbody>{report.projections.map(item=><tr key={item.month}><td>{monthLabel(item.month)}{item.belowTarget&&<small>Abaixo da meta</small>}</td><td className="pf-number">{money(item.openingCents)}</td><td className="pf-number">{money(item.receivableCents)}</td><td className="pf-number">{money(item.payableCents)}</td><td className="pf-number">{money(item.thirdPartyInCents)}</td><td className="pf-number">{money(item.thirdPartyOutCents)}{item.retainedFeesCents>0&&<small>Taxas retidas: {money(item.retainedFeesCents)}</small>}</td><td className="pf-number"><strong className={item.availableCents<0?'pf-negative':undefined}>{money(item.availableCents)}</strong></td></tr>)}</tbody></table></div><p className="pf-note-line">As parcelas de terceiros já estão incluídas nas entradas e saídas totais. Taxas retidas reduzem o valor a repassar, sem um novo depósito. A projeção mostra os compromissos registrados, não prevê novas vendas. Atualize os vencimentos conforme as negociações evoluírem.</p></section>
    <div className="pf-split"><section className="pf-panel"><div className="pf-heading"><h3>Ajustes manuais da competência</h3></div>{!state.adjustments.filter(adjustment=>adjustment.competenceDate.slice(0,7)===month).length?<p className="pf-muted">Nenhum ajuste manual. O resultado vem integralmente dos lançamentos.</p>:<div className="pf-list">{state.adjustments.filter(adjustment=>adjustment.competenceDate.slice(0,7)===month).map(adjustment=><div className="pf-list-row" key={adjustment.id}><span><strong>{adjustment.label}</strong><small>{DRE_GROUPS.find(group=>group.id===adjustment.group)?.label} · {adjustment.status==='cancelled'?'Cancelado':dateLabel(adjustment.competenceDate)}</small><small>{adjustment.reason}</small></span><strong>{money(adjustment.amountCents)}</strong>{adjustment.status==='active'&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel-adjustment',id:adjustment.id})}>Cancelar</button>}</div>)}</div>}</section><section className="pf-panel"><div className="pf-heading"><h3>Histórico do financeiro</h3></div>{!snapshot?.history?.length?<p className="pf-muted">As alterações financeiras serão registradas aqui.</p>:<ol className="pf-history">{snapshot.history.slice(0,30).map(item=><li key={item.id}><strong>{actionLabel(item.action)}</strong>{item.detail&&<div>{item.detail}</div>}<small>{item.author||'Administrador'} · {new Date(item.created_at??item.createdAt??'').toLocaleString('pt-BR')}</small></li>)}</ol>}</section></div>
  </>}
  {tab==='entries'&&<section className="pf-panel"><div className="pf-heading"><div><h2>Todo movimento tem um lugar.</h2><p>Competência, vencimento e pagamento acompanhados separadamente.</p></div><div className="pf-actions"><button className="ps-button" onClick={exportEntries} disabled={!entries.length}><Download size={15}/>Exportar CSV</button><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'entry'})}><Plus size={15}/>Novo lançamento</button></div></div><div className="pf-filters"><label>Buscar lançamento<input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Descrição ou categoria"/></label><label>Categoria<select value={categoryFilter} onChange={event=>setCategoryFilter(event.target.value)}><option value="">Todas as categorias</option>{categoryOptions.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label><label>Centro de custo<select value={centerFilter} onChange={event=>setCenterFilter(event.target.value)}><option value="">Todos os centros</option>{centers.map(center=><option key={center} value={center}>{center}</option>)}</select></label></div>{!entries.length?<Empty title="Sem lançamentos nesta seleção" description="Registre receitas e compromissos com a competência correta. Previsões ficam separadas do resultado realizado." action="Adicionar lançamento" onAction={()=>setModal({kind:'entry'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Lançamento</th><th>Vencimento</th><th>Situação</th><th className="pf-number">Valor</th><th>Ações</th></tr></thead><tbody>{entries.map(entry=><tr key={entry.id}><td><strong>{entry.description}</strong><small>{categoryLabel(entry.category)}{entry.costCenter?' · '+entry.costCenter:''}</small><small>Competência {dateLabel(entry.competenceDate)}{entry.recognition==='forecast'?' · Previsão':''}</small></td><td>{dateLabel(entry.dueDate)}{entry.settledDate&&<small>Baixa {dateLabel(entry.settledDate)}</small>}</td><td><span className={'pf-status pf-status--'+(entry.status==='open'?'pending':entry.status)}>{entryStatus(entry.status)}</span></td><td className="pf-number"><strong className={FINANCE_CATEGORIES.find(category=>category.id===entry.category)?.direction==='out'?'pf-negative':undefined}>{money(entry.amountCents)}</strong></td><td><div className="pf-actions">{entry.status==='open'&&<>{!entry.operationId&&<button className="ps-text-button" onClick={()=>setModal({kind:'entry',id:entry.id})}>Editar</button>}<button className="ps-text-button" disabled={!accountOptions.length} onClick={()=>setModal({kind:'settle',id:entry.id})}>Baixar</button></>}{entry.status!=='cancelled'&&!entry.operationId&&<button className="ps-text-button" onClick={()=>setModal({kind:'cancel',id:entry.id})}>Cancelar</button>}</div></td></tr>)}</tbody></table></div>}{!accountOptions.length&&entries.length>0&&<Notice>Cadastre uma conta em Contas para registrar recebimentos e pagamentos.</Notice>}</section>}
  {tab==='recurrences'&&<section className="pf-panel"><div className="pf-heading"><div><h2>Uma rotina financeira previsível.</h2><p>Honorários de administração, softwares, estrutura e outros compromissos mensais.</p></div><button className="ps-button ps-button--primary" onClick={()=>setModal({kind:'recurrence'})}><Plus size={16}/>Nova recorrência</button></div><Notice>MRR e ARR consideram as receitas recorrentes da EME ativas no mês atual. O aluguel bruto do proprietário não é receita da empresa. Gerar uma competência cria um lançamento para conferência.</Notice>{!state.recurrences.length?<Empty title="Organize os próximos meses" description="Comece pelas despesas fixas e pelos honorários mensais de administração. Nenhuma cobrança será enviada automaticamente." action="Cadastrar recorrência" onAction={()=>setModal({kind:'recurrence'})}/>:<div className="pf-table-wrap"><table className="pf-table"><thead><tr><th>Recorrência</th><th>Vigência</th><th>Vencimento</th><th className="pf-number">Mensal</th><th>Ações</th></tr></thead><tbody>{state.recurrences.map(recurrence=><tr key={recurrence.id}><td><strong>{recurrence.name}</strong><small>{categoryLabel(recurrence.category)}{!recurrence.active?' · Pausada':''}</small></td><td>{monthLabel(recurrence.startMonth)}<small>{recurrence.endMonth?'Até '+monthLabel(recurrence.endMonth):'Sem término definido'}</small></td><td>Dia {recurrence.dueDay}</td><td className="pf-number">{money(recurrence.amountCents)}</td><td><div className="pf-actions"><button className="ps-text-button" onClick={()=>setModal({kind:'recurrence',id:recurrence.id})}>Editar</button><button className="ps-text-button" disabled={!recurrence.active} onClick={()=>setModal({kind:'generate',id:recurrence.id})}>Gerar mês</button><button className="ps-text-button" onClick={()=>command('recurrence.save',{...recurrence,active:!recurrence.active},recurrence.active?'Recorrência pausada.':'Recorrência reativada.').catch(error=>setError(error.message))}>{recurrence.active?'Pausar':'Ativar'}</button></div></td></tr>)}</tbody></table></div>}</section>}
  {renderForm()}{toast&&<div className="ps-toast" role="status"><Check size={17}/><span>{toast}</span><button className="ps-icon" aria-label="Fechar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}
  </section>;
}
